#[doc = "The recipient's email address."]
pub fn email_address(&'a self) -> Result<EmailAddress<'a>, Error> {
    let val = self
        .properties
        .0
        .get("emailAddress")
        .ok_or(Error::NotFound)?;
    Ok(PropertyMap(Cow::Borrowed(
        val.as_object()
            .ok_or_else(|| Error::UnexpectedResponse(format!("{val:?}")))?,
    ))
    .into())
}
